/**
 * Formats a child process command failure for display. When the error has a
 * non-empty `stderr` property, the error message and stderr are joined with a
 * newline. Otherwise the error message is returned as-is.
 */
export function formatCommandFailure(
  command: string,
  error: { message: string; stderr?: string }
): string {
  if (error.stderr) {
    return `${error.message}\n${error.stderr}`;
  }
  return error.message;
}

